#define N 5
#define M 3

int alloc[N][M] = {{0,1,0},{2,0,0},{3,0,2},{2,1,1},{0,0,2}};
int need[N][M]  = {{7,4,3},{1,2,2},{6,0,0},{0,1,1},{4,3,1}};

int main(void) {
    int work[M] = {3, 3, 2};
    int finish[N] = {0};

    for (int tur = 0; tur < N; tur++) {
        for (int i = 0; i < N; i++) {
            if (finish[i]) continue;
            int olur = 1;
            for (int j = 0; j < M; j++)
                if (need[i][j] > work[j]) { olur = 0; break; }
            if (olur) {
                for (int j = 0; j < M; j++) work[j] += alloc[i][j];
                finish[i] = 1;
                printf("P%d tamam, work = %d %d %d\n", i, work[0], work[1], work[2]);
                break;
            }
        }
    }
    int hepsi = 1;
    for (int i = 0; i < N; i++) if (!finish[i]) hepsi = 0;
    printf("%s\n", hepsi ? "guvenli" : "guvensiz");
    return 0;
}

