#include <stdio.h>

int fifo(int *ref, int n, int F) {
    int mem[8];
    int sayi = 0, sira = 0, hata = 0;

    for (int i = 0; i < n; i++) {
        int var_mi = 0;
        for (int j = 0; j < sayi; j++)
            if (mem[j] == ref[i]) { var_mi = 1; break; }
        if (var_mi) continue;

        if (sayi < F) mem[sayi++] = ref[i];
        else { mem[sira] = ref[i]; sira = (sira + 1) % F; }
        hata++;
    }
    return hata;
}

