}

#include <stdio.h>

#define F 3

int main(void) {
    int ref[] = {7,0,1,2,0,3,0,4,2,3,0,3,2};
    int n = 13;
    int mem[F] = {-1, -1, -1};
    int son[F] = {0, 0, 0};
    int hata = 0;

    for (int i = 0; i < n; i++) {
        int bul = -1;
        for (int j = 0; j < F; j++)
            if (mem[j] == ref[i]) bul = j;

        if (bul >= 0) { son[bul] = i; continue; }   /* isabet: zamani guncelle */

        int kurban = 0;                              /* en eski kullanilan */
        for (int j = 1; j < F; j++)
            if (son[j] < son[kurban]) kurban = j;
        for (int j = 0; j < F; j++)                  /* bos cerceve varsa onu sec */
            if (mem[j] == -1) { kurban = j; break; }

        mem[kurban] = ref[i];
        son[kurban] = i;
        hata++;
    }
    printf("LRU hata = %d, isabet orani = %.2f\n", hata, (double)(n - hata) / n);
    return 0;
}

