#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int q[] = {98, 183, 37, 122, 14, 124, 65, 67};
    int n = 8;
    int alindi[8] = {0};
    int kafa = 53, toplam = 0;

    for (int adim = 0; adim < n; adim++) {
        int en_yakin = -1, en_kucuk = 1000000;
        for (int i = 0; i < n; i++) {
            if (alindi[i]) continue;
            int d = abs(q[i] - kafa);
            if (d < en_kucuk) { en_kucuk = d; en_yakin = i; }
        }
        toplam += en_kucuk;
        kafa = q[en_yakin];
        alindi[en_yakin] = 1;
    }
    printf("SSTF toplam = %d\n", toplam);

    kafa = 53; toplam = 0;
    for (int i = 0; i < n; i++) { toplam += abs(q[i] - kafa); kafa = q[i]; }
    printf("FCFS toplam = %d\n", toplam);
    return 0;
}

#include <stdio.h>

int main(void) {
    int q[] = {14, 37, 65, 67, 98, 122, 124, 183};   /* sirali */
    int n = 8;
    int baslangic = 53, maxc = 199;
    int kafa = baslangic, toplam = 0;

    for (int i = 0; i < n; i++)                 /* yukari: hizmet */
        if (q[i] >= baslangic) { toplam += q[i] - kafa; kafa = q[i]; }

    toplam += maxc - kafa;                      /* diskin sonuna */
    toplam += maxc;                             /* basa sar: 199 -> 0 */
    kafa = 0;

    for (int i = 0; i < n; i++)                 /* yukari: kalanlar */
        if (q[i] < baslangic) { toplam += q[i] - kafa; kafa = q[i]; }

    printf("C-SCAN toplam = %d\n", toplam);
    return 0;
}
